#include "Processor.h"
using namespace juce;
namespace noctrl {
const std::vector<FxDefinition>& fxDefinitions(){static const std::vector<FxDefinition> definitions={
 {"Bode",{{"SHIFT",-1000,1000,30,"Hz"},{"STEREO",-1,1,0,""}},1},
 {"Chorus",{{"RATE",.03f,10,.3f,"Hz",true},{"DEPTH",0,1,.35f,""},{"DELAY",1,30,12,"ms"},{"FEEDBACK",-.9f,.9f,.1f,""}},.5f},
 {"Compressor",{{"THRESHOLD",-60,0,-18,"dB"},{"RATIO",1,20,4,":1"},{"ATTACK",.1f,100,10,"ms",true},{"RELEASE",10,1000,100,"ms",true},{"MAKEUP",-12,24,0,"dB"}},1},
 {"Convolve",{{"PRE DELAY",0,200,0,"ms"},{"DAMP",500,20000,18000,"Hz",true},{"WIDTH",0,2,1,""},{"GAIN",-24,12,0,"dB"}},.3f},
 {"Delay",{{"TIME",1,2000,250,"ms",true},{"FEEDBACK",0,.95f,.35f,""},{"CROSS",0,1,.5f,""},{"LOW CUT",20,2000,30,"Hz",true},{"HIGH CUT",500,20000,15000,"Hz",true},{"SYNC",0,6,0,""}},.3f},
 {"Distortion",{{"DRIVE",0,36,12,"dB"},{"MODE",0,4,0,""},{"TONE",200,18000,8000,"Hz",true},{"OUTPUT",-24,12,-6,"dB"}},.5f},
 {"Equalizer",{{"LOW FREQ",30,800,120,"Hz",true},{"LOW GAIN",-18,18,0,"dB"},{"MID FREQ",100,8000,1000,"Hz",true},{"MID GAIN",-18,18,0,"dB"},{"HIGH FREQ",2000,18000,8000,"Hz",true},{"HIGH GAIN",-18,18,0,"dB"},{"Q",.2f,8,.7f,"",true}},1},
 {"Filter",{{"CUTOFF",20,20000,2000,"Hz",true},{"RESONANCE",0,.95f,.2f,""},{"MODE",0,3,0,""},{"DRIVE",0,18,0,"dB"}},1},
 {"Flanger",{{"RATE",.01f,10,.2f,"Hz",true},{"DEPTH",0,1,.7f,""},{"DELAY",.1f,10,2,"ms"},{"FEEDBACK",-.9f,.9f,.35f,""},{"STEREO",0,1,.5f,""}},.5f},
 {"Hyper / Dimension",{{"RATE",.02f,5,.4f,"Hz",true},{"DETUNE",0,1,.4f,""},{"HYPER",0,1,.5f,""},{"DIM SIZE",1,40,15,"ms"},{"DIM MIX",0,1,.3f,""},{"WIDTH",0,2,1,""}},.5f},
 {"Phaser",{{"RATE",.01f,10,.25f,"Hz",true},{"DEPTH",0,1,.6f,""},{"FREQUENCY",100,6000,1000,"Hz",true},{"FEEDBACK",-.9f,.9f,.2f,""}},.5f},
 {"Reverb",{{"SIZE",0,1,.7f,""},{"DAMP",0,1,.5f,""},{"PRE DELAY",0,200,10,"ms"},{"WIDTH",0,1,1,""},{"LOW CUT",20,2000,100,"Hz",true},{"HIGH CUT",1000,20000,12000,"Hz",true}},.25f},
 {"Splitter L/H",{{"CROSSOVER",20,18000,1000,"Hz",true},{"LOW GAIN",-60,12,0,"dB"},{"HIGH GAIN",-60,12,0,"dB"}},1},
 {"Splitter L/M/H",{{"LOW / MID",20,2000,300,"Hz",true},{"MID / HIGH",500,18000,3000,"Hz",true},{"LOW GAIN",-60,12,0,"dB"},{"MID GAIN",-60,12,0,"dB"},{"HIGH GAIN",-60,12,0,"dB"}},1},
 {"Splitter M/S",{{"MID GAIN",-60,12,0,"dB"},{"SIDE GAIN",-60,12,0,"dB"},{"WIDTH",0,2,1,""}},1},
 {"Utility",{{"GAIN",-60,12,0,"dB"},{"PAN",-1,1,0,""},{"WIDTH",0,2,1,""},{"INVERT L",0,1,0,""},{"INVERT R",0,1,0,""},{"DC CUT",0,1,0,""}},1},
 {"Trancegate",{{"RATE",0,5,2,""},{"DEPTH",0,100,100,"%"},{"GATE",5,100,75,"%"},{"ATTACK",.1f,30,2,"ms",true},{"RELEASE",.1f,80,5,"ms",true},{"STEREO",0,15,0,"steps"},{"STEPS",1,16,16,""}},1}
 };return definitions;}
void addFxParameters(AudioProcessorValueTreeState::ParameterLayout& layout,bool includeLegacy){for(int slot=0;slot<64;++slot){for(int c=0;c<8;++c)layout.add(std::make_unique<AudioParameterFloat>(fxId(slot,"p"+String(c)),"FX "+String(slot+1)+" control "+String(c+1),NormalisableRange<float>(0,1),.5f));layout.add(std::make_unique<AudioParameterFloat>(fxId(slot,"wet"),"FX "+String(slot+1)+" mix",NormalisableRange<float>(0,1),1));layout.add(std::make_unique<AudioParameterBool>(fxId(slot,"enabled"),"FX "+String(slot+1)+" enabled",true));}if(includeLegacy)layout.add(std::make_unique<AudioParameterBool>("fxLegacyMain","Synth FX before Main rack",true));
 for(int slot=0;slot<64;++slot){auto f=[&](String suffix,String title,float lo,float hi,float initial,float skew=1.f){layout.add(std::make_unique<AudioParameterFloat>(fxId(slot,suffix),"FX "+String(slot+1)+" "+title,NormalisableRange<float>(lo,hi,0,skew),initial));};for(int i=0;i<17;++i)f("shape"+String(i),"shape point "+String(i+1),-1,1,-1+i/8.f);layout.add(std::make_unique<AudioParameterBool>(fxId(slot,"customShape"),"Custom waveshaper",false));f("preCut","distortion pre low-pass",20,20000,20000,.3f);f("knee","compressor knee",0,24,0);layout.add(std::make_unique<AudioParameterBool>(fxId(slot,"multiband"),"3-band compressor",false));f("crossLow","low/mid crossover",40,1000,250,.4f);f("crossHigh","mid/high crossover",1000,12000,3500,.4f);for(int b=0;b<3;++b){f("bandGain"+String(b),"band makeup "+String(b+1),-18,18,0);f("bandThreshold"+String(b),"band threshold offset "+String(b+1),-24,24,0);}}
}
void addTrancegateParameters(AudioProcessorValueTreeState::ParameterLayout& layout){
 for(int slot=0;slot<64;++slot)for(int step=0;step<16;++step)
  layout.add(std::make_unique<AudioParameterFloat>(fxId(slot,"gate"+String(step)),"FX "+String(slot+1)+" gate step "+String(step+1),NormalisableRange<float>(0,1),trancegateDefault(step)));
}
ValueTree FxRackState::save()const{ValueTree tree("FxRack");for(auto& e:entries){ValueTree node("Effect");node.setProperty("slot",e.slot,nullptr);node.setProperty("type",e.type,nullptr);node.setProperty("bus",e.bus,nullptr);if(e.ir.getSize()){node.setProperty("ir",e.ir.toBase64Encoding(),nullptr);node.setProperty("irName",e.irName,nullptr);}tree.addChild(node,-1,nullptr);}return tree;}
struct RackBiquad {std::array<float,6> c{{1,0,0,1,0,0}};float z1=0,z2=0;float tick(float x){float y=c[0]/c[3]*x+z1;z1=c[1]/c[3]*x-c[4]/c[3]*y+z2;z2=c[2]/c[3]*x-c[5]/c[3]*y;return y;}};
class FxUnit {
 FxEntry entry;double sr;std::array<int,10> indices{};std::array<int,17> shapeIndices{};std::array<int,16> gateIndices{};double gatePosition=0;float gateGain[2]={};int customIndex=0,preIndex=0,kneeIndex=0,multiIndex=0,crossLowIndex=0,crossHighIndex=0;std::array<int,3> bandGainIndices{},bandThresholdIndices{};FxAnalysis& telemetry;AudioBuffer<float> work{2,8192},delay;
 dsp::Chorus<float> chorus,dimension;dsp::Phaser<float> phaser;Reverb reverb;std::unique_ptr<dsp::Convolution> convolve;
 std::array<SVF,2> filters;RackBiquad eq[3][2];float low[2]={},high[2]={},dcIn[2]={},dcOut[2]={};std::array<std::array<float,128>,2> hilbert{};std::array<float,127> hilbertCoeff{};int pos=0,hilbertPos=0;double phase=0,bodePhase[2]={};float envelope=0,bandEnvelope[3]={},preState[2]={};double visualPhase=0;
 float onePole(float x,float hz,float& state){float amount=1-std::exp(-MathConstants<float>::twoPi*jmin(hz,(float)sr*.43f)/(float)sr);state+=amount*(x-state);return state;}
 float readDelay(int channel,float time){int size=delay.getNumSamples();double cursor=std::fmod((double)pos-(double)time,(double)size);if(cursor<0)cursor+=size;if(cursor>=size)cursor=0;int index=jlimit(0,size-1,(int)cursor);float fraction=(float)(cursor-index);return delay.getSample(channel,index)*(1-fraction)+delay.getSample(channel,(index+1)%size)*fraction;}
 void width(float& l,float& r,float value){float mid=(l+r)*.5f,side=(l-r)*.5f*value;l=mid+side;r=mid-side;}
public:
 FxUnit(FxEntry e,AudioProcessorValueTreeState& state,double rate,FxAnalysis& data):entry(std::move(e)),sr(rate),telemetry(data){auto index=[&](String key){return state.getParameter(fxId(entry.slot,key))->getParameterIndex();};for(int i=0;i<16;++i)gateIndices[i]=index("gate"+String(i));for(int i=0;i<17;++i)shapeIndices[i]=index("shape"+String(i));customIndex=index("customShape");preIndex=index("preCut");kneeIndex=index("knee");multiIndex=index("multiband");crossLowIndex=index("crossLow");crossHighIndex=index("crossHigh");for(int b=0;b<3;++b){bandGainIndices[b]=index("bandGain"+String(b));bandThresholdIndices[b]=index("bandThreshold"+String(b));}for(int c=0;c<8;++c)indices[c]=state.getParameter(fxId(entry.slot,"p"+String(c)))->getParameterIndex();indices[8]=state.getParameter(fxId(entry.slot,"wet"))->getParameterIndex();indices[9]=state.getParameter(fxId(entry.slot,"enabled"))->getParameterIndex();dsp::ProcessSpec spec{sr,8192,2};if(entry.type==1||entry.type==9){chorus.prepare(spec);dimension.prepare(spec);}if(entry.type==10)phaser.prepare(spec);if(entry.type==11)reverb.setSampleRate(sr);if(entry.type==3||entry.type==4||entry.type==8||entry.type==11){delay.setSize(2,(int)(sr*2.2)+4);delay.clear();}
  if(entry.type==0)for(int k=0;k<127;++k){int t=k-63;hilbertCoeff[k]=t!=0&&std::abs(t)%2?2.f/(MathConstants<float>::pi*t)*(.54f-.46f*std::cos(MathConstants<float>::twoPi*k/126)):0;}
  if(entry.type==3){convolve=std::make_unique<dsp::Convolution>();AudioBuffer<float> ir;double irRate=sr;if(entry.ir.getSize()){AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(std::make_unique<MemoryInputStream>(entry.ir,false)));if(reader){int length=jmin((int)reader->lengthInSamples,(int)(reader->sampleRate*4));ir.setSize(2,length);reader->read(&ir,0,length,0,true,true);irRate=reader->sampleRate;}}if(ir.getNumSamples()==0){int length=(int)(sr*.8);ir.setSize(2,length);ir.clear();Random random(7183);for(int c=0;c<2;++c){ir.setSample(c,0,1);for(int i=1;i<length;++i){float t=i/(float)length;float v=random.nextFloat()*2-1;ir.setSample(c,i,v*.06f*std::exp(-8*t)*(i<sr*.012?0:1));}}}convolve->loadImpulseResponse(std::move(ir),irRate,dsp::Convolution::Stereo::yes,dsp::Convolution::Trim::no,dsp::Convolution::Normalise::yes);convolve->prepare(spec);}
 }
 void reset(){work.clear();delay.clear();chorus.reset();dimension.reset();phaser.reset();reverb.reset();if(convolve)convolve->reset();for(auto& f:filters)f.reset();for(auto& band:eq)for(auto& f:band){f.z1=f.z2=0;}for(int c=0;c<2;++c){low[c]=high[c]=dcIn[c]=dcOut[c]=0;hilbert[c].fill(0);}gatePosition=0;gateGain[0]=gateGain[1]=0;pos=hilbertPos=0;phase=0;bodePhase[0]=bodePhase[1]=0;envelope=0;visualPhase=0;for(auto& e:bandEnvelope)e=0;for(auto& v:preState)v=0;telemetry.reduction.store(0);telemetry.phase.store(0);}
 void process(AudioBuffer<float>& buffer,int start,int n,const std::vector<float>& values,double bpm,double beat=std::numeric_limits<double>::quiet_NaN()){if(values[(size_t)indices[9]]<.5f){telemetry.reduction.store(0);return;}float wet=values[(size_t)indices[8]];if(wet<=0){telemetry.reduction.store(0);return;}const auto& def=fxDefinitions()[(size_t)entry.type];float grPeak=0,bandIn[3]={},bandOut[3]={},bandGr[3]={};float v[8]={};for(size_t c=0;c<def.controls.size();++c)v[c]=def.controls[c].from(values[(size_t)indices[c]]);for(int c=0;c<2;++c)work.copyFrom(c,0,buffer,c,start,n);
  if(entry.type==1||entry.type==9){chorus.setRate(v[0]);chorus.setDepth(v[1]);chorus.setCentreDelay(entry.type==9?12:v[2]);chorus.setFeedback(entry.type==9?.1f:v[3]);chorus.setMix(entry.type==9?v[2]:1.f);dsp::AudioBlock<float> block(work);auto part=block.getSubBlock(0,(size_t)n);dsp::ProcessContextReplacing<float> context(part);chorus.process(context);if(entry.type==9){dimension.setRate(.12f);dimension.setDepth(.15f);dimension.setCentreDelay(v[3]);dimension.setFeedback(0);dimension.setMix(v[4]);dimension.process(context);for(int i=0;i<n;++i){float l=work.getSample(0,i),r=work.getSample(1,i);width(l,r,v[5]);work.setSample(0,i,l);work.setSample(1,i,r);}}}
  else if(entry.type==10){phaser.setRate(v[0]);phaser.setDepth(v[1]);phaser.setCentreFrequency(jmin(v[2],(float)sr*.4f));phaser.setFeedback(v[3]);phaser.setMix(1);dsp::AudioBlock<float> block(work);auto part=block.getSubBlock(0,(size_t)n);dsp::ProcessContextReplacing<float> context(part);phaser.process(context);}
  else if(entry.type==3){dsp::AudioBlock<float> block(work);auto part=block.getSubBlock(0,(size_t)n);dsp::ProcessContextReplacing<float> context(part);convolve->process(context);for(int i=0;i<n;++i){float pair[2];for(int c=0;c<2;++c){float x=onePole(work.getSample(c,i),v[1],low[c])*Decibels::decibelsToGain(v[3]);delay.setSample(c,pos,x);pair[c]=v[0]>0?readDelay(c,(float)(sr*v[0]/1000)):x;}width(pair[0],pair[1],v[2]);for(int c=0;c<2;++c)work.setSample(c,i,pair[c]);pos=(pos+1)%delay.getNumSamples();}}
  else if(entry.type==11){for(int i=0;i<n;++i){for(int c=0;c<2;++c){float x=work.getSample(c,i);delay.setSample(c,pos,x);float delayed=v[2]>0?readDelay(c,(float)(sr*v[2]/1000)):x;work.setSample(c,i,delayed);}pos=(pos+1)%delay.getNumSamples();}Reverb::Parameters rp;rp.roomSize=v[0];rp.damping=v[1];rp.wetLevel=1;rp.dryLevel=0;rp.width=v[3];rp.freezeMode=0;reverb.setParameters(rp);reverb.processStereo(work.getWritePointer(0),work.getWritePointer(1),n);for(int c=0;c<2;++c)for(int i=0;i<n;++i){float x=work.getSample(c,i);x-=onePole(x,v[4],low[c]);work.setSample(c,i,onePole(x,v[5],high[c]));}}
  else if(entry.type==16){
   const int steps=jlimit(1,16,roundToInt(v[6])),offset=roundToInt(v[5]);
   const double stepBeats=trancegateStepBeats(roundToInt(v[0]));
   const double increment=jlimit(20.,400.,std::isfinite(bpm)?bpm:120.)/(60.*sr*stepBeats);
   if(std::isfinite(beat)){gatePosition=std::fmod(beat/stepBeats,(double)steps);if(gatePosition<0)gatePosition+=steps;}
   const float attack=(float)std::exp(-1./(sr*v[3]*.001)),release=(float)std::exp(-1./(sr*v[4]*.001));
   for(int i=0;i<n;++i){int step=(int)gatePosition;float within=(float)(gatePosition-step);
    for(int c=0;c<2;++c){int index=(step+(c?offset:0))%steps;float target=within<v[2]*.01f?values[(size_t)gateIndices[index]]:0.f;
     float coefficient=target>gateGain[c]?attack:release;gateGain[c]=target+(gateGain[c]-target)*coefficient;
     work.setSample(c,i,work.getSample(c,i)*(1-v[1]*.01f+v[1]*.01f*gateGain[c]));}
    gatePosition+=increment;gatePosition=std::fmod(gatePosition,(double)steps);
   }
   telemetry.phase.store((float)(gatePosition/steps),std::memory_order_relaxed);
  }
  else {if(entry.type==6){auto hz=[&](float value){return jmin(value,(float)sr*.43f);};for(int c=0;c<2;++c){eq[0][c].c=dsp::IIR::ArrayCoefficients<float>::makeLowShelf(sr,hz(v[0]),.707f,Decibels::decibelsToGain(v[1]));eq[1][c].c=dsp::IIR::ArrayCoefficients<float>::makePeakFilter(sr,hz(v[2]),v[6],Decibels::decibelsToGain(v[3]));eq[2][c].c=dsp::IIR::ArrayCoefficients<float>::makeHighShelf(sr,hz(v[4]),.707f,Decibels::decibelsToGain(v[5]));}}if(entry.type==7)for(auto& f:filters)f.configure(v[0],v[1],sr);
   for(int i=0;i<n;++i){float input[2]={work.getSample(0,i),work.getSample(1,i)},out[2]={input[0],input[1]};
    if(entry.type==0){for(int c=0;c<2;++c){hilbert[c][hilbertPos]=input[c];float imaginary=0;for(int k=0;k<127;++k)imaginary+=hilbert[c][(hilbertPos-k+128)%128]*hilbertCoeff[k];float real=hilbert[c][(hilbertPos-63+128)%128];double angle=bodePhase[c];out[c]=real*(float)std::cos(angle)-imaginary*(float)std::sin(angle);bodePhase[c]=std::fmod(angle+MathConstants<double>::twoPi*v[0]*(c==1?1+v[1]:1)/sr,MathConstants<double>::twoPi);}hilbertPos=(hilbertPos+1)%128;phase+=MathConstants<double>::twoPi*v[0]/sr;if(std::abs(phase)>MathConstants<double>::twoPi)phase=std::fmod(phase,MathConstants<double>::twoPi);}
    else if(entry.type==2){auto compression=[&](float peak,float& detector,float threshold){float coefficient=(float)std::exp(-1/(sr*(peak>detector?v[2]:v[3])*.001));detector=coefficient*detector+(1-coefficient)*peak;float db=Decibels::gainToDecibels(detector,-100.f),above=db-threshold,knee=values[(size_t)kneeIndex],cut=0;if(knee>0&&above>-knee*.5f&&above<knee*.5f)cut=(1-1/v[1])*std::pow(above+knee*.5f,2.f)/(2*knee);else if(above>0)cut=above*(1-1/v[1]);return jmax(0.f,cut);};
     if(values[(size_t)multiIndex]>.5f){float bands[3][2];for(int c=0;c<2;++c){float lo=onePole(input[c],values[(size_t)crossLowIndex],low[c]),upper=onePole(input[c],values[(size_t)crossHighIndex],high[c]);bands[0][c]=lo;bands[1][c]=upper-lo;bands[2][c]=input[c]-upper;out[c]=0;}for(int b=0;b<3;++b){float peak=jmax(std::abs(bands[b][0]),std::abs(bands[b][1]));float cut=compression(peak,bandEnvelope[b],v[0]+values[(size_t)bandThresholdIndices[b]]);float gain=Decibels::decibelsToGain(v[4]+values[(size_t)bandGainIndices[b]]-cut);bandIn[b]=jmax(bandIn[b],peak);bandOut[b]=jmax(bandOut[b],peak*gain);bandGr[b]=jmax(bandGr[b],cut);grPeak=jmax(grPeak,cut);for(int c=0;c<2;++c)out[c]+=bands[b][c]*gain;}}
     else {float cut=compression(jmax(std::abs(input[0]),std::abs(input[1])),envelope,v[0]);float gain=Decibels::decibelsToGain(-cut+v[4]);grPeak=jmax(grPeak,cut);for(int c=0;c<2;++c)out[c]*=gain;}}

    else if(entry.type==4){int sync=roundToInt(v[5]);float beats[]={0,.25f,.5f,1,2,4,8};float time=(float)(sr*(sync>0?beats[jlimit(1,6,sync)]*60/bpm:v[0]*.001));time=jlimit(1.f,(float)delay.getNumSamples()-2,time);float taps[2]={readDelay(0,time),readDelay(1,time)};for(int c=0;c<2;++c){float tap=taps[c]-onePole(taps[c],v[3],low[c]);tap=onePole(tap,v[4],high[c]);delay.setSample(c,pos,input[c]+(taps[c]*(1-v[2])+taps[1-c]*v[2])*v[1]);out[c]=tap;}pos=(pos+1)%delay.getNumSamples();}
    else if(entry.type==5){int mode=roundToInt(v[1]);for(int c=0;c<2;++c){float dry=input[c];float preCut=values[(size_t)preIndex];if(preCut<19999)dry=onePole(dry,preCut,preState[c]);float x=dry*Decibels::decibelsToGain(v[0]);if(values[(size_t)customIndex]>.5f){float at=(jlimit(-1.f,1.f,x)+1)*8;int k=jmin(15,(int)at);float f=at-k;x=values[(size_t)shapeIndices[k]]*(1-f)+values[(size_t)shapeIndices[k+1]]*f;}else if(mode==0)x=std::tanh(x);else if(mode==1)x=jlimit(-1.f,1.f,x);else if(mode==2)x=x/(1+std::abs(x));else if(mode==3)x=2*std::abs(2*((x+1)/4-std::floor((x+1)/4+.5f)))-1;else x=std::round(jlimit(-1.f,1.f,x)*16)/16;out[c]=onePole(x,v[2],low[c])*Decibels::decibelsToGain(v[3]);}}
    else if(entry.type==6){for(int c=0;c<2;++c)for(auto& band:eq)out[c]=band[c].tick(out[c]);}
    else if(entry.type==7){int mode=roundToInt(v[2]);for(int c=0;c<2;++c){float x=input[c];if(v[3]>0)x=std::tanh(x*Decibels::decibelsToGain(v[3]));float y=filters[c].process(x,mode==3?2:mode);out[c]=mode==3?x-(2-1.94f*v[1])*y:y;}}
    else if(entry.type==8){for(int c=0;c<2;++c){float time=(float)(sr*.001*(v[2]+v[1]*v[2]*.9f*std::sin(phase+c*v[4]*MathConstants<double>::pi)));float tap=readDelay(c,jmax(1.f,time));delay.setSample(c,pos,input[c]+tap*v[3]);out[c]=tap;}pos=(pos+1)%delay.getNumSamples();phase+=MathConstants<double>::twoPi*v[0]/sr;if(phase>MathConstants<double>::twoPi)phase-=MathConstants<double>::twoPi;}
    else if(entry.type==12){for(int c=0;c<2;++c){float lo=onePole(input[c],v[0],low[c]);out[c]=lo*mixDbGain(v[1])+(input[c]-lo)*mixDbGain(v[2]);}}
    else if(entry.type==13){float f1=jmin(v[0],v[1]),f2=jmax(v[0],v[1]);for(int c=0;c<2;++c){float lo=onePole(input[c],f1,low[c]),top=onePole(input[c],f2,high[c]);out[c]=lo*mixDbGain(v[2])+(top-lo)*mixDbGain(v[3])+(input[c]-top)*mixDbGain(v[4]);}}
    else if(entry.type==14){float mid=(input[0]+input[1])*.5f*mixDbGain(v[0]),side=(input[0]-input[1])*.5f*mixDbGain(v[1])*v[2];out[0]=mid+side;out[1]=mid-side;}
    else if(entry.type==15){width(out[0],out[1],v[2]);for(int c=0;c<2;++c){if(v[5]>.5f){float y=out[c]-dcIn[c]+.995f*dcOut[c];dcIn[c]=out[c];dcOut[c]=y;out[c]=y;}out[c]*=mixDbGain(v[0])*std::sqrt(c==0?1-v[1]:1+v[1])*(v[3+c]>.5f?-1:1);}}
    for(int c=0;c<2;++c)work.setSample(c,i,out[c]);
   }
  }
  if(entry.type==1||entry.type==9||entry.type==10){visualPhase=std::fmod(visualPhase+v[0]*n/sr,1.);telemetry.phase.store((float)visualPhase,std::memory_order_relaxed);}else if(entry.type==8)telemetry.phase.store((float)(phase/MathConstants<double>::twoPi),std::memory_order_relaxed);telemetry.reduction.store(grPeak,std::memory_order_relaxed);for(int b=0;b<3;++b){telemetry.bandInput[b].store(bandIn[b],std::memory_order_relaxed);telemetry.bandOutput[b].store(bandOut[b],std::memory_order_relaxed);telemetry.bandReduction[b].store(bandGr[b],std::memory_order_relaxed);}
  for(int c=0;c<2;++c)for(int i=0;i<n;++i){float dry=buffer.getSample(c,start+i),value=dry+(work.getSample(c,i)-dry)*wet;buffer.setSample(c,start+i,std::isfinite(value)?jlimit(-32.f,32.f,value):0.f);}
 }
};
struct NativeFxAdapter::Impl {
 FxAnalysis data;FxUnit unit;std::vector<float> values;std::array<int,16> controls{};int enabled,multi,knee;
 Impl(int type,AudioProcessorValueTreeState& state,double sr):unit(FxEntry{0,type,0,{},{}},state,sr,data){
  auto add=[&](String key){auto* parameter=state.getParameter(fxId(0,key));int index=parameter->getParameterIndex();if(values.size()<=(size_t)index)values.resize(index+1);values[(size_t)index]=parameter->convertFrom0to1(parameter->getDefaultValue());return index;};
  for(int i=0;i<8;++i)controls[i]=add("p"+String(i));controls[8]=add("wet");enabled=add("enabled");values[enabled]=1;multi=add("multiband");knee=add("knee");for(int i=0;i<17;++i)add("shape"+String(i));for(auto key:{"customShape","preCut","crossLow","crossHigh"})add(key);for(int i=0;i<3;++i){controls[9+i]=add("bandGain"+String(i));controls[12+i]=add("bandThreshold"+String(i));}controls[15]=multi;
 }
};
NativeFxAdapter::NativeFxAdapter(int type,AudioProcessorValueTreeState& state,double sr):impl(std::make_unique<Impl>(type,state,sr)){}
NativeFxAdapter::~NativeFxAdapter()=default;
void NativeFxAdapter::reset(){impl->unit.reset();}
void NativeFxAdapter::process(AudioBuffer<float>& b,int start,int n,const std::array<float,16>& controls,double bpm){for(int i=0;i<16;++i)impl->values[(size_t)impl->controls[i]]=controls[i];impl->unit.process(b,start,n,impl->values,bpm);}
FxRackRuntime::FxRackRuntime(const FxRackState& state,AudioProcessorValueTreeState& parameters,double sr,FxMeterValues& levels,FxAnalysisValues& data):meters(levels),analysis(data),sampleRate(sr){for(auto& e:state.entries){units.push_back(std::make_unique<FxUnit>(e,parameters,sr,analysis[e.slot]));buses.push_back(e.bus);slots.push_back(e.slot);for(auto& channel:meters[e.slot])channel.store(0,std::memory_order_relaxed);analysis[e.slot].rate.store((float)sr,std::memory_order_relaxed);analysis[e.slot].cursor.store(0,std::memory_order_relaxed);for(auto& sample:analysis[e.slot].input)sample.store(0,std::memory_order_relaxed);for(auto& sample:analysis[e.slot].output)sample.store(0,std::memory_order_relaxed);}}
FxRackRuntime::~FxRackRuntime()=default;
void FxRackRuntime::reset(){for(auto& unit:units)unit->reset();for(int slot:slots)for(auto& channel:meters[slot])channel.store(0,std::memory_order_relaxed);}
void FxRackRuntime::process(int bus,AudioBuffer<float>& buffer,int start,int n,const std::vector<float>& values,double bpm,double beat){for(size_t i=0;i<units.size();++i)if(buses[i]==bus){auto& data=analysis[slots[i]];data.tempo.store((float)bpm,std::memory_order_relaxed);data.rate.store((float)sampleRate,std::memory_order_relaxed);unsigned cursor=data.cursor.load(std::memory_order_relaxed);for(int sample=0;sample<n;++sample)data.input[(cursor+sample)%1024].store((buffer.getSample(0,start+sample)+buffer.getSample(1,start+sample))*.5f,std::memory_order_relaxed);float decay=(float)std::exp(-n/(sampleRate*.3));for(int channel=0;channel<2;++channel){auto& peak=data.inputPeak[channel];peak.store(jmax(buffer.getMagnitude(channel,start,n),peak.load(std::memory_order_relaxed)*decay),std::memory_order_relaxed);}units[i]->process(buffer,start,n,values,bpm,beat);double ll=0,rr=0,lr=0;for(int sample=0;sample<n;++sample){double l=buffer.getSample(0,start+sample),r=buffer.getSample(1,start+sample);ll+=l*l;rr+=r*r;lr+=l*r;}data.correlation.store(ll*rr>1e-15?(float)jlimit(-1.,1.,lr/std::sqrt(ll*rr)):0.f,std::memory_order_relaxed);for(int sample=0;sample<n;++sample)data.output[(cursor+sample)%1024].store((buffer.getSample(0,start+sample)+buffer.getSample(1,start+sample))*.5f,std::memory_order_relaxed);data.cursor.store(cursor+n,std::memory_order_release);float release=(float)std::exp(-n/(sampleRate*.3));for(int channel=0;channel<2;++channel){auto& level=meters[slots[i]][channel];float peak=n>0?buffer.getMagnitude(channel,start,n):0.f;level.store(jmax(std::isfinite(peak)?peak:0.f,level.load(std::memory_order_relaxed)*release),std::memory_order_relaxed);}}}
void SynthProcessor::rebuildFxRack(){auto next=std::make_shared<FxRackRuntime>(*rack(),state,sampleRate,fxMeters,*fxAnalysis);auto old=std::atomic_exchange(&fxRuntime,next);if(old)retiredFx.push_back(std::move(old));retiredFx.erase(std::remove_if(retiredFx.begin(),retiredFx.end(),[](const auto& r){return r.use_count()==1;}),retiredFx.end());}
int SynthProcessor::addFx(int bus,int type){if((effectOnly&&bus!=0)||bus<0||bus>2||type<0||type>=(int)fxDefinitions().size())return -1;auto next=std::make_shared<FxRackState>(*rack());int slot=0;for(;slot<64;++slot){bool used=false;for(auto& e:next->entries)used|=e.slot==slot;if(!used)break;}if(slot==64)return -1;const auto& def=fxDefinitions()[(size_t)type];for(size_t c=0;c<def.controls.size();++c)set(fxId(slot,"p"+String(c)),def.controls[c].to(def.controls[c].initial));set(fxId(slot,"wet"),def.wet);set(fxId(slot,"enabled"),1);set(fxId(slot,"customShape"),0);set(fxId(slot,"preCut"),20000);set(fxId(slot,"knee"),0);set(fxId(slot,"multiband"),0);set(fxId(slot,"crossLow"),250);set(fxId(slot,"crossHigh"),3500);for(int i=0;i<16;++i)set(fxId(slot,"gate"+String(i)),trancegateDefault(i));for(int i=0;i<17;++i)set(fxId(slot,"shape"+String(i)),-1+i/8.f);for(int b=0;b<3;++b){set(fxId(slot,"bandGain"+String(b)),0);set(fxId(slot,"bandThreshold"+String(b)),0);}next->entries.push_back({slot,type,bus,{},{}});std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();return slot;}
void SynthProcessor::removeFx(int slot){auto live=liveMods();for(auto& link:live->links)if(link.target.startsWith("rack")&&link.target.substring(4).getIntValue()==slot+1)removeLiveMod(link.source,link.target);auto next=std::make_shared<FxRackState>(*rack());next->entries.erase(std::remove_if(next->entries.begin(),next->entries.end(),[&](const auto& e){return e.slot==slot;}),next->entries.end());for(int c=0;c<8;++c)removeMacroLink(fxId(slot,"p"+String(c)));removeMacroLink(fxId(slot,"wet"));for(int i=0;i<16;++i)removeMacroLink(fxId(slot,"gate"+String(i)));for(int i=0;i<17;++i)removeMacroLink(fxId(slot,"shape"+String(i)));for(auto key:{"preCut","knee","crossLow","crossHigh","bandGain0","bandGain1","bandGain2","bandThreshold0","bandThreshold1","bandThreshold2"})removeMacroLink(fxId(slot,key));std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();}
void SynthProcessor::moveFx(int slot,int delta){auto next=std::make_shared<FxRackState>(*rack());for(size_t i=0;i<next->entries.size();++i)if(next->entries[i].slot==slot){int index=(int)i;for(int j=index+(delta<0?-1:1);j>=0&&j<(int)next->entries.size();j+=delta<0?-1:1)if(next->entries[(size_t)j].bus==next->entries[i].bus){std::swap(next->entries[i],next->entries[(size_t)j]);break;}break;}std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();}
void SynthProcessor::moveFxTo(int slot,int index){auto next=std::make_shared<FxRackState>(*rack());auto it=std::find_if(next->entries.begin(),next->entries.end(),[&](const auto& e){return e.slot==slot;});if(it==next->entries.end())return;auto entry=*it;next->entries.erase(it);int position=0;auto insert=next->entries.end();for(auto scan=next->entries.begin();scan!=next->entries.end();++scan)if(scan->bus==entry.bus){if(position++==index){insert=scan;break;}}next->entries.insert(insert,entry);std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();}
bool SynthProcessor::loadFxIR(int slot,const File& file,String& error){if(!file.existsAsFile()||file.getSize()>16*1024*1024){error="Choose an impulse response smaller than 16 MB.";return false;}MemoryBlock bytes;if(!file.loadFileAsData(bytes)){error="Could not read the impulse response.";return false;}AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(std::make_unique<MemoryInputStream>(bytes,false)));if(!reader||reader->lengthInSamples==0){error="Could not decode the impulse response.";return false;}auto next=std::make_shared<FxRackState>(*rack());bool found=false;for(auto& e:next->entries)if(e.slot==slot&&e.type==3){e.ir=std::move(bytes);e.irName=file.getFileName();found=true;break;}if(!found){error="Convolve slot was removed.";return false;}std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();return true;}
void SynthProcessor::restoreFxRack(const ValueTree& tree){auto next=std::make_shared<FxRackState>();std::array<bool,64> used{};for(auto child:tree){int slot=(int)child.getProperty("slot",-1),type=(int)child.getProperty("type",-1),bus=(int)child.getProperty("bus",-1);if((effectOnly&&bus!=0)||slot<0||slot>=64||type<0||type>=(int)fxDefinitions().size()||bus<0||bus>2||used[slot])continue;used[slot]=true;FxEntry e{slot,type,bus,{},{}};String encoded=child["ir"].toString();if(encoded.length()<24*1024*1024)e.ir.fromBase64Encoding(encoded);e.irName=child["irName"];next->entries.push_back(std::move(e));}std::atomic_store(&fxRackState,std::shared_ptr<const FxRackState>(next));rebuildFxRack();}
}
